const E = (n: string, v: VideoSource, s: SetScheme[], rest?: string, note?: string): Exercise => {
  const source = (Array.isArray(v) ? v.length > 0 : !!v) ? v : (VIDEO_BY_EXERCISE[n] ?? '');
  const videos = (Array.isArray(source) ? source : source ? [source] : []).map((url) => url.trim());
  return {
    n,
    v: videos.find(Boolean) ?? '',
    videos: videos.length > 1 ? videos : undefined,
    s,
    rest: rest || '1-2 мин',
    note: note || '',
  };
};

const B = (block: string, blockRest: string, exercise: Exercise): Exercise => ({
  ...exercise,
  block,
  blockRest,
});

/* Разминочные блоки */
const ROLL = () => E('Раскатка на массажном ролике и мячике', V.roll, [[1, '8-12 минут', '']], 'без отдыха');
const ACT = () => E('Активация с отягощением / Активация с резиной', V.akt, [[2, 'круг × 8-10', '30-40%']], 'без отдыха; 1-2 мин между кругами');
const CORE_ACT = () => E('Активация стабилизаторов корпуса / На фитболе', V.fit, [[1, 'круг × 10-15', '30-40%']], 'без отдыха');
const WU = (): Exercise[] => [ACT(), CORE_ACT()];
const MOB = () => E('Мобильность', V.mobility, [[1, 'круг × 10-15', '']], 'без отдыха');
const MAN = () => E('Комплекс для вращательной манжеты плеча с эспандером', V.man, [[2, 'круг × 8-10', '30-40%']], 'без отдыха; 1-2 мин между кругами');
const MOBP = () => E('Мобильность плеч', V.mobilityShoulders, [[1, 'круг × 10-15', '']], 'без отдыха');
const TEST_WU = (): Exercise[] => [ROLL(), ACT(), MAN(), CORE_ACT(), MOB(), MOBP()];

