/** Базовые показатели для замеров */
export const BASE_METR: [key: string, label: string][] = [
  ['weight', 'Вес тела, кг'],
  ['jumpst', 'Прыжок с места, см'],
  ['jumprun', 'Прыжок с разбега, см'],
  ['reach', 'Высота касания, см'],
];

/** Все известные упражнения (для подсказок в редакторе) */
export function knownExercises(prog: Day[]) {
  const map = new Map<string, Exercise>();
  const grab = (d: Day) => d.e.forEach((x) => { if (x.n && !map.has(x.n)) map.set(x.n, x); });
  DEFAULT_PROGRAM.forEach(grab);
  prog.forEach(grab);
  return map;
}
